/**
 * Sound event ↔ sound card matching.
 *
 * A generated event belongs to the card with the same `config_id`. Legacy
 * events without one fall back to `prompt_index` (the card's array position;
 * speech-line TTS encodes `cardIndex * 10000 + line`).
 */

interface MatchableSound {
  config_id?: string;
  prompt_index?: number | null;
}

interface MatchableConfig {
  config_id?: string;
}

/** Whether `sound` was generated by the card at `index`. */
export function soundMatchesCard(
  sound: MatchableSound,
  configs: ReadonlyArray<MatchableConfig>,
  index: number,
): boolean {
  const configId = configs[index]?.config_id;
  if (configId && sound.config_id) return sound.config_id === configId;
  if (sound.prompt_index === index) return true;
  const pi = sound.prompt_index;
  if (pi != null && pi >= 10000 && Math.floor(pi / 10000) === index) return true;
  return false;
}

/** Index of the card that generated `sound`, or -1. */
export function findCardIndexForSound(
  sound: MatchableSound,
  configs: ReadonlyArray<MatchableConfig>,
): number {
  return configs.findIndex((_, index) => soundMatchesCard(sound, configs, index));
}
